insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('faf8934a-6158-5fea-a807-5e4777dcffab', '439ad9b5-c69f-5118-881a-a55d1c3ee596', 'Mountain · In-Season DUP (8wk)', 'Strength', 'Intermediate', 8, '{"1": "In-season undulating for ski/snowboard: mountain days are the training priority \u2014 the gym keeps the legs honest. Day 1 heavy low-dose, Day 2 power/reactive, Day 3 eccentric-prehab (optional \u2014 skip after big mountain weekends). Cap RPE 8.", "4": "Deload week \u2014 2 sets across the board.", "7": "Peak-season maintenance: hold loads, never chase fatigue.", "8": "Final week \u2014 movement quality and stiffness only."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('47b13d89-73f4-5cd0-93a9-5b9b95234b9d', '439ad9b5-c69f-5118-881a-a55d1c3ee596', 'Mountain · Conjugate Eccentric-Power (12wk)', 'Power', 'Advanced', 12, '{"1": "Conjugate adapted for mountain athletes: ME lower rotates every 2 wks (wks 1-2 Trap-Bar Deadlift), a dynamic-effort lateral/reactive day, a dedicated eccentric-isometric day (the ski-specific engine), and an upper/core day. Deloads at 4 and 8.", "3": "ME lift rotates: Front Squat (heavy 3).", "4": "Deload week.", "5": "ME lift rotates: Romanian Deadlift (heavy 3).", "7": "ME lift returns to Trap-Bar Deadlift \u2014 beat week 2.", "8": "Deload week.", "9": "ME lift free choice \u2014 strongest variation. Eccentric tempos slow further.", "12": "Test week: heavy pull, best jump & bound, longest wall sit. Then go ride."}'::jsonb) on conflict (id) do nothing;
